import{_ as t,a as d,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"View GDPR Request","description":"","frontmatter":{"outline":false,"examples":[{"id":"view-gdpr-request","title":"View a GDPR Request","description":"Retrieve a single GDPR data request owned by the authenticated customer.","query":"query GdprRequest($id: ID!) {\\n  gdprRequest(id: $id) {\\n    _id\\n    type\\n    status\\n    message\\n    email\\n    revokedAt\\n    createdAt\\n    updatedAt\\n    customer {\\n      _id\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"id\\": \\"/api/shop/gdpr-requests/12\\"\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"gdprRequest\\": {\\n      \\"_id\\": 12,\\n      \\"type\\": \\"delete\\",\\n      \\"status\\": \\"pending\\",\\n      \\"message\\": \\"Please delete my account data.\\",\\n      \\"email\\": \\"jane@example.com\\",\\n      \\"revokedAt\\": null,\\n      \\"createdAt\\": \\"2026-06-25T10:30:00+00:00\\",\\n      \\"updatedAt\\": \\"2026-06-25T10:30:00+00:00\\",\\n      \\"customer\\": {\\n        \\"_id\\": 7\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"GDPR disabled","cause":"GDPR data requests are turned off in the store's admin configuration","solution":"Re-enable GDPR from the admin configuration before calling this query"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The request does not exist or is not owned by the authenticated customer","solution":"Only request IDs belonging to the logged-in customer can be viewed"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/gdpr-requests/queries/view-gdpr-request.md","filePath":"api/graphql-api/shop/gdpr-requests/queries/view-gdpr-request.md","lastUpdated":1786429091000}`),o={name:"api/graphql-api/shop/gdpr-requests/queries/view-gdpr-request.md"};function s(n,e,i,u,c,h){return r(),d("div",null,e[0]||(e[0]=[a('<h1 id="view-gdpr-request" tabindex="-1">View GDPR Request <a class="header-anchor" href="#view-gdpr-request" aria-label="Permalink to &quot;View GDPR Request&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>gdprRequest</code> query returns a single GDPR data request <strong>owned by the authenticated customer</strong>. If the request does not exist or belongs to a different customer, the query returns a not-found error — a customer can only view their own requests.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This query requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="gdpr-must-be-enabled" tabindex="-1">GDPR must be enabled <a class="header-anchor" href="#gdpr-must-be-enabled" aria-label="Permalink to &quot;GDPR must be enabled&quot;">​</a></h2><p>If GDPR data requests are disabled in the store&#39;s admin configuration, the query fails with the message <strong>&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</strong> in <code>errors[]</code>. The feature has been turned off on the admin side.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>✅ Yes</td><td>The request IRI, e.g. <code>/api/shop/gdpr-requests/12</code>.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>Int!</code></td><td>Numeric request ID.</td></tr><tr><td><code>type</code></td><td><code>String!</code></td><td>Request type: <code>delete</code> or <code>update</code>.</td></tr><tr><td><code>status</code></td><td><code>String!</code></td><td>Request status: <code>pending</code>, <code>processing</code>, <code>declined</code>, <code>approved</code>, <code>revoked</code>.</td></tr><tr><td><code>message</code></td><td><code>String!</code></td><td>The customer&#39;s message describing the request.</td></tr><tr><td><code>email</code></td><td><code>String!</code></td><td>Email address tied to the request.</td></tr><tr><td><code>revokedAt</code></td><td><code>String</code></td><td>Timestamp when the request was revoked, or <code>null</code>.</td></tr><tr><td><code>createdAt</code></td><td><code>String</code></td><td>Request creation timestamp.</td></tr><tr><td><code>updatedAt</code></td><td><code>String</code></td><td>Request last update timestamp.</td></tr><tr><td><code>successMessage</code></td><td><code>String</code></td><td>Confirmation text. Populated only on create, revoke, and delete results — <code>null</code> when reading.</td></tr><tr><td><code>customer</code></td><td><code>Customer</code></td><td>The customer who owns the request.</td></tr><tr><td><code>customer._id</code></td><td><code>Int!</code></td><td>Numeric customer ID of the owner.</td></tr></tbody></table><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/gdpr-requests/queries/list-gdpr-requests.html">List GDPR Requests</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/mutations/revoke-gdpr-request.html">Revoke a GDPR Request</a></li><li><a href="/api/graphql-api/shop/gdpr-requests/">GDPR Requests Overview</a></li></ul>',13)]))}const q=t(o,[["render",s]]);export{p as __pageData,q as default};
